import { Router } from 'express';

const router = Router();

router.post('/', async (req, res) => {
  const { text } = req.body;
  if (!text) return res.status(400).json({ error: 'No text provided' });

  const DEEPGRAM_KEY = process.env.DEEPGRAM_API_KEY;

  if (DEEPGRAM_KEY) {
    try {
      const response = await fetch(
        'https://api.deepgram.com/v1/speak?model=aura-2-odysseus-en',
        {
          method: 'POST',
          headers: {
            Authorization: `Token ${DEEPGRAM_KEY}`,
            'Content-Type': 'text/plain',
          },
          body: text,
        },
      );

      if (!response.ok) {
        throw new Error(`Deepgram TTS failed: ${response.status}`);
      }

      const audioBuffer = await response.arrayBuffer();
      res.set('Content-Type', 'audio/mpeg');
      res.set('Content-Length', audioBuffer.byteLength.toString());
      res.send(Buffer.from(audioBuffer));
      return;
    } catch (err) {
      console.error('[TTS] Deepgram error, falling back to mock:', err.message);
    }
  }

  // Mock TTS — return a small silent MP3 so the client doesn't error
  const silentMp3 = Buffer.from(
    '',
    'base64',
  );
  res.set('Content-Type', 'audio/mpeg');
  res.send(silentMp3);
});

export default router;
